# Table extraction: detect grid lines in ASCII-art tables, split into rows/columns.
text = """+-----+-----+\n| a   | b   |\n+-----+-----+\n| 1   | 2   |\n+-----+-----+""".replace("\\n", "\n")
def extract(t):
    lines = [l for l in t.splitlines() if l.strip()]
    # find column boundaries from '+' intersections in border lines
    bounds = None
    for l in lines:
        if set(l.strip()) <= set("+-"):
            b = [i for i, c in enumerate(l) if c == "+"]
            if len(b) > 1: bounds = b; break
    rows = []
    for l in lines:
        if set(l.strip()) <= set("+-"): continue
        if bounds and "|" in l:
            cells = []
            for a, b in zip(bounds, bounds[1:]):
                cells.append(l[a+1:b].strip())
            rows.append(cells)
        elif "|" in l:
            rows.append([c.strip() for c in l.strip().strip("|").split("|")])
    return rows
rows = extract(text)
for r in rows: print(r)
print("shape:", len(rows), "x", (len(rows[0]) if rows else 0))

